/** 按厂商 id 取元数据，未知 id 回退腾讯云（兼容未记录 provider 的历史密钥） */
export function providerMeta(id) {
  return PROVIDER_META[id] || PROVIDER_META.tencent;
}

/** 厂商显示名 */
export function providerName(id) {
  return providerMeta(id).name;
}

/** 该厂商当前是否已开放连接能力（planned 表示尚未支持） */
export function providerSupported(id) {
  return providerMeta(id).kind !== 'planned';
}

/** 厂商列表（按界面顺序） */
export function providerList() {
  return ORDER.map((id) => PROVIDER_META[id]);
}

/** 生成厂商图形 SVG（等比缩放到 44×44 视图，适配任意 viewBox 宽高比） */
export function providerLogoSvg(id) {
  const s = SHAPES[id];
  if (!s) return '';
  const paths = s.paths
    .map((p) => `<path d="${p.d}" fill="${p.fill}"/>`)
    .join('');
  return `<svg viewBox="${s.viewBox}" preserveAspectRatio="xMidYMid meet" aria-hidden="true">${paths}</svg>`;
}

/**
 * 生成「白底容器 + 居中图形」的徽标块
 * @param {string} id   厂商 id
 * @param {object} opt  { size: 'sm' | 'md' | 'lg'，与 .pv-logo--* 对应 }
 */
export function providerLogo(id, opt = {}) {
  const size = opt.size === 'sm' ? ' pv-logo--sm' : opt.size === 'lg' ? ' pv-logo--lg' : '';
  return `<span class="pv-logo${size}">${providerLogoSvg(id)}</span>`;
}
